fn concat(mut a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Pre-allocate enough space for all elements to avoid multiple reallocations.
    a.reserve(b.len());
    // Append all elements of `b` onto the end of `a`.
    a.extend(b);
    // Now `a` is the concatenation of the original `a` and `b`.
    a
}

